export type InfracaoCtb = {
  codigo: string
  desdobramento: number
  /** "7455-0" */
  chave: string
  descricao: string
  gravidade: MultaGravidadeImportada | null
  pontos: number | null
  multiplicador: number
  amparo: string
  infrator: string
  /** Valor da multa em R$ (null quando o valor não é fixo, ex.: multa NIC). */
  valor: number | null
}

/** Valores-base do art. 258 do CTB (Lei 13.281/2016). */
export const VALOR_BASE_POR_GRAVIDADE: Record<MultaGravidadeImportada, number> = {
  leve: 88.38,
  media: 130.16,
  grave: 195.23,
  gravissima: 293.47,
}

export const INFRACOES_CTB: InfracaoCtb[] = INFRACOES_ROWS.map(
  ([codigo, desdobramento, descricao, gravidade, pontos, multiplicador, amparo, infrator]) => ({
    codigo,
    desdobramento,
    chave: `${codigo}-${desdobramento}`,
    descricao,
    gravidade,
    pontos,
    multiplicador,
    amparo,
    infrator,
    valor: gravidade ? Math.round(VALOR_BASE_POR_GRAVIDADE[gravidade] * multiplicador * 100) / 100 : null,
  }),
)

/**
 * Busca pelo código digitado: aceita "7455", "74550", "7455-0" ou "7455 0".
 * Sem desdobramento, retorna todas as variações do código.
 */
export function buscarInfracoes(valor: string): InfracaoCtb[] {
  const digits = valor.replace(/\D/g, "")
  if (digits.length < 4) return []
  const codigo = digits.slice(0, 4)
  const desdobramento = digits.length > 4 ? Number(digits.slice(4, 5)) : null
  return INFRACOES_CTB.filter(
    (item) => item.codigo === codigo && (desdobramento === null || item.desdobramento === desdobramento),
  )
}
